    ("MITTS_LOG_COMPILE", "1", "Log each compile action and every build-script hit or miss with its key, and the inputs of the build-script key.", "MITTS_LOG_COMPILE=1 mitts build"),
    ("MITTS_LOG_KEYS", "any", "Log the inputs of every unit key, and units whose key had to use an absolute manifest directory. For finding out why a unit missed the cache.", "MITTS_LOG_KEYS=1 mitts build"),
