    ("MITTS_CRATES_IO_URL", "url", "Where <code>.crate</code> archives are downloaded from. Default <code>https://static.crates.io/crates</code>. For a mirror or an offline proxy.", "MITTS_CRATES_IO_URL=https://mirror.example/crates"),
    ("MITTS_SPARSE_INDEX_URL", "url", "The sparse registry index used for crates.io. For a mirror.", "MITTS_SPARSE_INDEX_URL=https://mirror.example/index"),
    ("MITTS_LLVM_COV", "path", "The <code>llvm-cov</code> binary used by <code>mitts coverage</code>, instead of the automatic lookup.", "MITTS_LLVM_COV=/opt/llvm/bin/llvm-cov"),
    ("MITTS_LLVM_PROFDATA", "path", "The <code>llvm-profdata</code> binary used by <code>mitts coverage</code>, instead of the automatic lookup.", "MITTS_LLVM_PROFDATA=/opt/llvm/bin/llvm-profdata"),
    ("MITTS_VERSION", "vX.Y.Z", "<b>Installer.</b> Release to install instead of the latest. Pinning skips the latest-release lookup.", "MITTS_VERSION=v0.3.34 sh install.sh"),
